package org.ev6.launchpad;
import java.io.*;import java.util.zip.*;
public final class RootTool {
 static final File DIR=new File("/data/local/ev6-launchpad");static final File MV=new File("/data/data/org.ev6.musicvibe/files");
 static final String PKG="org.ev6.musicvibe",BOOT="org.ev6.musicvibe/.BootReceiver";
 public static void main(String[] args){try{String a=args[0];DIR.mkdirs();
  if(a.equals("adb-status")){System.out.println(AdbControl.status());}
  else if(a.matches("adb-(usb|tcp)-(on|off)")){String[] v=a.split("-");AdbControl.apply(v[1],v[2].equals("on"));System.out.println(AdbControl.status());}
  else if(a.startsWith("vibe-config:")){String[] v=a.split(":");if(v.length!=4||!(v[1].equals("true")||v[1].equals("false"))||!v[2].matches("clockwise|counterclockwise|random"))throw new IOException("Invalid options");int seconds=Integer.parseInt(v[3]);if(seconds<2||seconds>20)throw new IOException("Invalid period");installed();checked("am","startservice","-n",PKG+"/.BreathService","-a","CONFIG","--ez","autoboot",v[1],"--es","mode",v[2],"--ei","period_ms",Integer.toString(seconds*1000));boolean saved=false;for(int attempt=0;attempt<15;attempt++){Thread.sleep(100);try{org.json.JSONObject config=new org.json.JSONObject(options());if(config.optBoolean("autoboot",!Boolean.parseBoolean(v[1]))==Boolean.parseBoolean(v[1])&&config.optString("mode","").equals(v[2])&&config.optInt("period_ms",0)==seconds*1000){saved=true;break;}}catch(Exception ignored){}}if(!saved)throw new IOException("\u8a2d\u5b9a\u5132\u5b58\u5c1a\u672a\u78ba\u8a8d");System.out.println("\u8a2d\u5b9a\u5df2\u5132\u5b58");}
  else if(a.equals("vibe-status")){System.out.println(read(new File(MV,"status"),2000));System.out.println("\u904b\u4f5c\u65d7\u6a19："+new File(MV,"armed").exists()+"；\u5f85\u9084\u539f："+new File(MV,"restore.json").exists());System.out.println(cmd("dumpsys","package",PKG));}
  else if(a.equals("vibe-diag")){System.out.println("STATE_ENABLED="+vibeActive());System.out.println("OPTIONS="+options());for(String n:new String[]{"status","last-restored","last-manual-handoff","diag-main.jsonl","diag-guard.jsonl","diag-boot.jsonl"})System.out.println("\n"+n+"\n"+read(new File(MV,n),10000));}
  else if(a.equals("vibe-enable")){installed();checked("am","startservice","-n",PKG+"/.BreathService","-a","START");Thread.sleep(1500);if(!new File(MV,"armed").exists())throw new IOException("\u555f\u52d5\u5c1a\u672a\u6210\u529f："+read(new File(MV,"status"),2000));System.out.println("\u5df2\u555f\u7528\u547c\u5438\u71c8");}
  else if(a.equals("vibe-disable")||a.equals("vibe-remove")){installed();if(a.equals("vibe-remove"))backup();checked("am","startservice","-n",PKG+"/.BreathService","-a","STOP");boolean done=false;for(int i=0;i<60;i++){Thread.sleep(200);if(!new File(MV,"armed").exists()&&!new File(MV,"restore.json").exists()){done=true;break;}}if(!done)throw new IOException("\u9084\u539f\u4ecd\u5f85\u5b8c\u6210，\u5df2\u4fdd\u7559\u7a0b\u5f0f\u8207\u5099\u4efd："+read(new File(MV,"status"),2000));if(a.equals("vibe-remove")){String s=cmd("pm","uninstall",PKG);if(!s.contains("Success"))throw new IOException(s);System.out.println("\u5df2\u9084\u539f\u4e26\u79fb\u9664\u547c\u5438\u71c8；\u5099\u4efd\u4fdd\u7559\u65bc "+DIR+"/backups");}else System.out.println("\u5df2\u505c\u7528；"+read(new File(MV,"status"),2000));}
  else if(a.matches("voice-(enable|disable|diag)")){voice(a.substring(6));}
  else if(a.equals("pad-enable")){new File(DIR,"disabled").delete();checked("pm","enable","org.ev6.launchpad/.BootReceiver");System.out.println("\u5df2\u555f\u7528\u9577\u6309\u5165\u53e3\u8207\u958b\u6a5f\u555f\u52d5");}
  else if(a.equals("pad-disable")||a.equals("pad-remove")){new File(DIR,"disabled").createNewFile();checked("pm","disable","org.ev6.launchpad/.BootReceiver");if(a.equals("pad-remove")){String ap=cmd("pm","path","org.ev6.launchpad").trim().replace("package:","");File b=new File(DIR,"backups");b.mkdirs();copy(new File(ap),new File(b,"Launchpad-"+System.currentTimeMillis()+".apk"));cleanupBoot();String s=cmd("pm","uninstall","org.ev6.launchpad");if(!s.contains("Success"))throw new IOException(s);new File(DIR,"start.sh").delete();}else System.out.println("\u5df2\u505c\u7528\u9577\u6309\u5165\u53e3；\u4e0d\u5f71\u97ff\u547c\u5438\u71c8");}
  else if(a.equals("pad-diag")){System.out.println("STATE_ENABLED="+!new File(DIR,"disabled").exists());System.out.println("\u9577\u6309\u5165\u53e3\u505c\u7528："+new File(DIR,"disabled").exists());System.out.println(read(new File(DIR,"knob.log"),24000));}
  else throw new IOException("Unknown action");System.out.println("RESULT_OK");
 }catch(Exception e){e.printStackTrace();System.exit(1);}}
 static String options()throws Exception{File f=new File(MV,"options.json");return f.exists()?read(f,4096):"{\"autoboot\":true,\"mode\":\"clockwise\",\"period_ms\":8000}";}
 static void voice(String action)throws Exception{File dir=new File("/data/local/ev6-voice-window");File flag=new File(dir,"enabled");if(action.equals("diag")){boolean alive=false;try{alive=voicePing();}catch(Exception ignored){}System.out.println("STATE_ENABLED="+(flag.exists()&&alive));System.out.println("\u6a21\u578b：Vosk small-cn-0.22\n\u4f4d\u7f6e：/storage/navi2/ev6-vosk\n\u6309\u4f4f\u8a9e\u97f3\u9375\u6536\u97f3，\u653e\u958b\u8fa8\u8b58\n\u51b7\u6c23：\u6253\u958b／\u95dc\u9589\u51b7\u6c23，\u6eab\u5ea6\u8abf\u5230 17～27 \u5ea6（\u5de6\u53f3\u5169\u5074）\n\u51b7\u6c23\u57f7\u884c："+(new File(dir,"allow-climate").exists()?"\u5df2\u5141\u8a31":"\u95dc\u9589")+"\n\u56db\u7a97\u6307\u4ee4：\u81ea\u52d5\u5168\u958b／\u5168\u95dc；\u5404\u7a97\u56de\u5831\u6709\u6548\u624d\u57f7\u884c\n\u8eca\u7a97\u57f7\u884c："+(new File(dir,"allow-window").exists()?"\u5df2\u5141\u8a31":"\u95dc\u9589，\u5f85\u5be6\u8eca\u6e2c\u8a66")+"\n\u8eca\u9580：\u89e3\u9396／\u4e0a\u9396；\u4f9d\u56db\u9580\u56de\u5831\u78ba\u8a8d\u7d50\u679c\n\u8fa8\u8b58\u9580\u6abb：0.50；\u5df2\u52a0\u5165\u89c0\u5bdf\u5230\u7684\u8aa4\u5b57\u6821\u6b63\n\u6309\u9375／\u9ea5\u514b\u98a8：\u5df2\u5be6\u8eca\u78ba\u8a8d；\u8fa8\u8b58\u53ca\u57f7\u884c\u7d50\u679c\u898b\u4e0b\u65b9\u7d00\u9304");System.out.println(read(new File("/data/data/org.ev6.voicewindow/files/state.json"),6000));System.out.println(read(new File("/data/data/org.ev6.voicewindow/files/voice.jsonl"),20000));System.out.println(read(new File(dir,"daemon.log"),12000));System.out.println(read(new File(dir,"window-auto.last"),2000));return;}if(action.equals("disable")){boolean windowWasActive=new File(dir,"window-auto.active").exists();flag.delete();checked("am","startservice","-n","org.ev6.voicewindow/.VoiceService","-a","STOP");Thread.sleep(1000);checked("am","force-stop","org.ev6.voicewindow");System.out.println(windowWasActive?"\u5df2\u505c\u7528\u8a9e\u97f3\u8fa8\u8b58；\u5df2\u9001\u51fa\u7684\u81ea\u52d5\u8eca\u7a97\u5982\u9700\u4e2d\u6b62\u8acb\u7528\u5be6\u9ad4\u6309\u9215":"\u5df2\u505c\u7528\u8a9e\u97f3\u8fa8\u8b58\u4e26\u91cb\u653e\u9ea5\u514b\u98a8");return;}if(!cmd("pm","path","org.ev6.voicewindow").contains("package:"))throw new IOException("\u8a9e\u97f3\u8fa8\u8b58\u5c1a\u672a\u5b89\u88dd");dir.mkdirs();flag.createNewFile();try{voiceBoot();checked("sh",new File(dir,"start.sh").getPath());boolean ready=false;for(int i=0;i<25;i++){try{if(voicePing()){ready=true;break;}}catch(Exception ignored){}Thread.sleep(100);}if(!ready)throw new IOException("\u8a9e\u97f3\u6309\u9375\u6a4b\u63a5\u5c1a\u672a\u5c31\u7dd2");System.out.println("\u5df2\u555f\u7528；\u6a21\u578b\u8f09\u5165\u4e2d，\u8acb\u7a0d\u5019");}catch(Exception e){flag.delete();try{cmd("am","force-stop","org.ev6.voicewindow");}catch(Exception ignored){}throw e;}}
 static boolean voicePing()throws Exception{android.net.LocalSocket s=new android.net.LocalSocket();try{s.connect(new android.net.LocalSocketAddress("ev6.voicewindow.v1"));s.setSoTimeout(1000);if(s.getPeerCredentials().getUid()!=0)return false;java.io.DataOutputStream out=new java.io.DataOutputStream(s.getOutputStream());out.writeUTF("ping");out.flush();return new java.io.DataInputStream(s.getInputStream()).readUTF().equals("ready");}finally{s.close();}}
 static void voiceBoot()throws Exception{File f=new File("/system/etc/install-recovery.sh");String text=read(f,64000);String line="/system/bin/sh /data/local/ev6-voice-window/start.sh >/dev/null 2>&1 &\n";if(text.contains(line))return;File dir=new File("/data/local/ev6-voice-window");File backup=new File(dir,"install-recovery.before");if(!backup.exists())copy(f,backup);String next=text.startsWith("#!/system/bin/sh\n")?text.replace("#!/system/bin/sh\n","#!/system/bin/sh\n"+line):line+text;cmd("mount","-o","remount,rw","/system");try{File tmp=new File(f.getPath()+".voice-next");FileOutputStream out=new FileOutputStream(tmp);out.write(next.getBytes("UTF-8"));out.getFD().sync();out.close();checked("chmod","755",tmp.getPath());if(!tmp.renameTo(f))throw new IOException("\u958b\u6a5f\u5165\u53e3\u5beb\u5165\u5931\u6557");if(!read(f,64000).equals(next))throw new IOException("\u958b\u6a5f\u5165\u53e3\u9a57\u8b49\u5931\u6557");}finally{cmd("mount","-o","remount,ro","/system");}}
 static boolean vibeActive(){try{long age=android.os.SystemClock.elapsedRealtime()-Long.parseLong(read(new File(MV,"heartbeat"),64).trim());return new File(MV,"armed").exists()&&age>=0&&age<6000;}catch(Exception e){return false;}}
 static void cleanupBoot()throws Exception{File f=new File("/system/etc/install-recovery.sh");String text=read(f,64000);String line="/system/bin/sh /data/local/ev6-launchpad/start.sh >/dev/null 2>&1 &\n";if(!text.contains(line))return;String restored=text.replace(line,"");cmd("mount","-o","remount,rw","/system");try{File next=new File("/system/etc/install-recovery.sh.launchpad-next");FileOutputStream out=new FileOutputStream(next);try{out.write(restored.getBytes("UTF-8"));out.getFD().sync();}finally{out.close();}cmd("chmod","755",next.getPath());if(!next.renameTo(f))throw new IOException("\u7121\u6cd5\u79fb\u9664\u958b\u6a5f\u5165\u53e3，\u4fdd\u7559\u7a0b\u5f0f");if(!read(f,64000).equals(restored))throw new IOException("\u958b\u6a5f\u5165\u53e3\u9a57\u8b49\u5931\u6557");}finally{cmd("mount","-o","remount,ro","/system");}}
 static void installed()throws Exception{if(!cmd("pm","path",PKG).contains("package:"))throw new IOException("\u547c\u5438\u71c8\u5c1a\u672a\u5b89\u88dd");}
 static String cmd(String... a)throws Exception{return BoundedProcess.run(new ProcessBuilder(a),8000,120000);}

 static void checked(String...a)throws Exception{String s=cmd(a);if(s.contains("Error:")||s.contains("Exception"))throw new IOException(s);}
 static String read(File f,int limit)throws Exception{if(!f.exists())return "（\u7121）";RandomAccessFile in=new RandomAccessFile(f,"r");try{long pos=Math.max(0,in.length()-limit);in.seek(pos);byte[] b=new byte[(int)(in.length()-pos)];in.readFully(b);return new String(b,"UTF-8");}finally{in.close();}}
 static void copy(File s,File d)throws Exception{FileInputStream in=new FileInputStream(s);FileOutputStream out=new FileOutputStream(d);try{byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);out.getFD().sync();}finally{in.close();out.close();}if(s.length()!=d.length()||!hash(s).equals(hash(d)))throw new IOException("Backup verification failed");}
 static String hash(File f)throws Exception{java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");FileInputStream in=new FileInputStream(f);try{byte[] b=new byte[8192];int n;while((n=in.read(b))>0)md.update(b,0,n);}finally{in.close();}StringBuilder s=new StringBuilder();for(byte b:md.digest())s.append(String.format("%02x",b&255));return s.toString();}
 static void backup()throws Exception{File b=new File(DIR,"backups/musicvibe-"+System.currentTimeMillis());b.mkdirs();String ap=cmd("pm","path",PKG).trim().replace("package:","");copy(new File(ap),new File(b,"Music-Vibe.apk"));ZipOutputStream z=new ZipOutputStream(new FileOutputStream(new File(b,"data.zip")));try{zip(z,new File("/data/data/"+PKG),"");}finally{z.close();}ZipFile verify=new ZipFile(new File(b,"data.zip"));try{java.util.Enumeration<? extends ZipEntry> entries=verify.entries();byte[] a=new byte[8192];while(entries.hasMoreElements()){InputStream in=verify.getInputStream(entries.nextElement());try{while(in.read(a)>0){}}finally{in.close();}}}finally{verify.close();}System.out.println("\u79fb\u9664\u524d\u5099\u4efd\u5df2\u9a57\u8b49："+b);}
 static void zip(ZipOutputStream z,File f,String name)throws Exception{if(f.isDirectory()){File[] fs=f.listFiles();if(fs!=null)for(File c:fs)zip(z,c,name+c.getName()+(c.isDirectory()?"/":""));}else{z.putNextEntry(new ZipEntry(name));FileInputStream in=new FileInputStream(f);try{byte[] a=new byte[8192];int n;while((n=in.read(a))>0)z.write(a,0,n);}finally{in.close();}z.closeEntry();}}
}
